// npm run tokens: copies the design system into src/theme (design-system/project): tokens.json → tokens.css,
// components/bundle.css → bundle.css, assets/Icons/*.svg → icons.ts. Do not edit the generated files.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';

const ds = new URL('../../design-system/project/', import.meta.url);
const out = new URL('../src/theme/', import.meta.url);
const tokens = JSON.parse(readFileSync(new URL('tokens.json', ds), 'utf8'));
const header = 'Generated by scripts/gen-tokens.mjs from design-system/project. Do not edit.';

// Every token becomes a custom property of the same name; {name} references become var(--name).
const vars = ['color', 'spacing', 'radius', 'shadow', 'layout']
  .flatMap((group) => tokens[group].tokens)
  .map((t) => `  --${t.name}: ${t.value.replace(/^\{(.+)\}$/, 'var(--$1)')};`);
// The fonts are served from this site (scripts/fonts.mjs) under their variable-font names.
const sans = tokens.type.families.sans.replace('"Nunito Sans", "Noto Sans SC"', '"Nunito Sans Variable", "Noto Sans SC Variable"');
// Each type style becomes a class of the same name (.display, .title, …); bundle.css adjusts them on phones.
const types = tokens.type.groups.flatMap((g) => g.styles).map((s) =>
  `.${s.name} { margin: 0; font: ${s.fontWeight} ${s.fontSize}/${s.lineHeight} var(--font-sans);` +
  `${s.letterSpacing ? ` letter-spacing: ${s.letterSpacing};` : ''}${s.name === 'amount' ? ' font-variant-numeric: tabular-nums;' : ''} }`);
writeFileSync(new URL('tokens.css', out),
  `/* ${header} */\n:root {\n${vars.join('\n')}\n  --font-sans: ${sans};\n}\n${types.join('\n')}\n`);

// The component styles as they are, without the Google Fonts import.
const bundle = readFileSync(new URL('components/bundle.css', ds), 'utf8').replace(/^@import url\([^)]*\);\n+/m, '');
writeFileSync(new URL('bundle.css', out), `/* ${header} */\n${bundle}`);

// Each icon keeps its inner SVG elements; colour comes from the text (stroke="currentColor" in components/Icon).
const icons = {};
const iconDir = new URL('assets/Icons/', ds);
for (const file of readdirSync(iconDir).filter((f) => f.endsWith('.svg')).sort()) {
  const svg = readFileSync(new URL(file, iconDir), 'utf8');
  icons[file.replace('.svg', '')] = svg.match(/<svg[^>]*>(.*)<\/svg>/s)[1].trim();
}
writeFileSync(
  new URL('icons.ts', out),
  `// ${header}\n// Lucide icons (ISC licence) chosen for 海豚云; see design-system/project/assets/Icons/README.md.\n` +
    `export const icons = ${JSON.stringify(icons, null, 2)} as const;\n\nexport type IconName = keyof typeof icons;\n`,
);
console.log(`tokens: ${vars.length} variables; bundle.css: ${bundle.length} bytes; icons: ${Object.keys(icons).length}`);
